103	class IndexedDbRepository<T extends BaseRecord> implements Repository<T> {
104	  readonly #database: IDBDatabase;
105	  readonly #storeName: StoreName;
106	  readonly #now: () => string;
107	  readonly #createId: () => string;
108	  readonly #validate?: Validator<T>;
109	
110	  constructor(
111	    database: IDBDatabase,
112	    storeName: StoreName,
113	    dependencies: Required<RepositoryDependencies>,
114	    validate?: Validator<T>,
115	  ) {
116	    this.#database = database;
117	    this.#storeName = storeName;
118	    this.#now = dependencies.now;
119	    this.#createId = dependencies.createId;
120	    this.#validate = validate;
121	  }
122	
123	  async create(input: CreateInput<T>): Promise<T> {
124	    const timestamp = this.#now();
125	    assertAbsoluteIsoTimestamp(timestamp, "createdAt");
126	    const record = {
127	      ...input,
128	      id: this.#createId(),
129	      createdAt: timestamp,
130	      updatedAt: timestamp,
131	    } as T;
132	    validateBase(record);
133	    this.#validate?.(record);
134	
135	    await runTransaction(this.#database, this.#storeName, "readwrite", (transaction) =>
136	      requestToPromise(transaction.objectStore(this.#storeName).add(record)),
137	    );
138	    return record;
139	  }
140	
141	  get(id: string): Promise<T | undefined> {
142	    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
143	      requestToPromise<T | undefined>(
144	        transaction.objectStore(this.#storeName).get(id),
145	      ),
146	    );
147	  }
148	
149	  list(): Promise<T[]> {
150	    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
151	      requestToPromise<T[]>(transaction.objectStore(this.#storeName).getAll()),
152	    );
153	  }
154	
155	  async update(id: string, patch: UpdateInput<T>): Promise<T> {
156	    return runTransaction(this.#database, this.#storeName, "readwrite", async (transaction) => {
157	      const store = transaction.objectStore(this.#storeName);
158	      const existing = await requestToPromise<T | undefined>(store.get(id));
159	      if (!existing) {
160	        throw new Error(`Record not found: ${id}`);
161	      }
162	
163	      const updated = {
164	        ...existing,
165	        ...patch,
