139	function extensionOf(fileName: string): string | undefined {
140	  const dot = fileName.lastIndexOf(".");
141	  return dot < 0 ? undefined : fileName.slice(dot + 1).toLowerCase();
142	}
143	
144	function fileMetadata(file: File, fileType?: JobDescriptionFileType): JobDescriptionFileMetadata {
145	  return { fileName: file.name, mimeType: file.type, fileSize: file.size, ...(fileType ? { fileType } : {}) };
146	}
147	
148	function errorFor(
149	  code: JobDescriptionIngestionErrorCode,
150	  message: string,
151	  action: JobDescriptionRecoveryAction,
152	  metadata: JobDescriptionFileMetadata,
153	  existingJobDescriptionId?: string,
154	): JobDescriptionIngestionError {
155	  return new JobDescriptionIngestionError({ code, message, action, metadata, ...(existingJobDescriptionId ? { existingJobDescriptionId } : {}) });
156	}
157	
158	function validateFileMetadata(file: File): JobDescriptionFileType {
159	  const extension = extensionOf(file.name);
160	  if (extension !== "pdf" && extension !== "docx") {
161	    throw errorFor("unsupported-format", "Only PDF and DOCX job description files are supported.", ACTIONS.chooseSupported, fileMetadata(file));
162	  }
163	  if (file.size > MAX_JOB_DESCRIPTION_FILE_SIZE) {
164	    throw errorFor("file-too-large", "The job description file exceeds the 25 MB limit.", ACTIONS.chooseSmaller, fileMetadata(file, extension));
165	  }
166	  if (file.type.toLowerCase() !== MIME_TYPES[extension]) {
167	    throw errorFor("type-mismatch", "The job description extension and MIME type do not match.", ACTIONS.chooseMatching, fileMetadata(file, extension));
168	  }
169	  return extension;
170	}
171	
172	function hasPrefix(data: Uint8Array, prefix: readonly number[]): boolean {
173	  return prefix.every((byte, index) => data[index] === byte);
174	}
175	
176	function validateFileContents(file: File, fileType: JobDescriptionFileType, data: Uint8Array): void {
177	  let valid = false;
178	  if (fileType === "pdf") {
179	    const source = new TextDecoder("latin1").decode(data);
180	    valid = hasPrefix(data, [0x25, 0x50, 0x44, 0x46, 0x2d]) && source.includes("%%EOF");
181	  } else if (hasPrefix(data, [0x50, 0x4b, 0x03, 0x04])) {
182	    try {
183	      const required = new Set(["[Content_Types].xml", "word/document.xml"]);
184	      const entries = unzipSync(data, { filter: (entry) => required.has(entry.name) });
185	      valid = [...required].every((name) => entries[name] !== undefined);
186	    } catch {
187	      valid = false;
188	    }
189	  }
190	  if (!valid) {
191	    throw errorFor("invalid-file", `The selected ${fileType.toUpperCase()} file is invalid.`, ACTIONS.chooseValid, fileMetadata(file, fileType));
192	  }
193	}
