195	async function sha256(data: ArrayBuffer): Promise<string> {
196	  const digest = await crypto.subtle.digest("SHA-256", data);
197	  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
198	}
