240	  async ingestPaste(applicationId: string, text: string): Promise<PasteResult> {
241	    if (!text.trim()) throw new Error("Pasted job description text cannot be empty.");
242	    const timestamp = this.#now();
243	    assertAbsoluteIsoTimestamp(timestamp, "JobDescription.createdAt");
244	    const jobDescriptionId = this.#createId();
245	    const textRecord: JobDescriptionText = {
246	      id: this.#createId(), createdAt: timestamp, updatedAt: timestamp,
247	      jobDescriptionId, kind: "pasted", text,
248	    };
249	    const jobDescription: JobDescription = {
250	      id: jobDescriptionId, createdAt: timestamp, updatedAt: timestamp,
251	      applicationId, textSource: "pasted",
252	    };
253	    await runTransaction(this.#database, [STORE_NAMES.applications, STORE_NAMES.jobDescriptions, STORE_NAMES.jobDescriptionTexts], "readwrite", async (tx) => {
254	      const app = await requestToPromise<Application | undefined>(tx.objectStore(STORE_NAMES.applications).get(applicationId));
255	      if (!app) throw new Error(`Application not found: ${applicationId}`);
256	      await requestToPromise(tx.objectStore(STORE_NAMES.jobDescriptions).add(jobDescription));
257	      await requestToPromise(tx.objectStore(STORE_NAMES.jobDescriptionTexts).add(textRecord));
258	    });
259	    this.#logger({ event: "job-description-pasted", metadata: metadataFor(jobDescription) });
260	    return { jobDescription, text: textRecord };
261	  }
