340	      requestToPromise<JobDescription | undefined>(tx.objectStore(STORE_NAMES.jobDescriptions).get(jobDescriptionId)),
341	    );
342	    if (jobDescription?.textSource === "manual") return this.getText(jobDescriptionId, "manual");
343	    if (jobDescription?.textSource === "extracted" || jobDescription?.textSource === "pasted") {
344	      return (await this.getText(jobDescriptionId, "confirmed")) ?? this.getText(jobDescriptionId, "manual");
