364	  async confirmText(jobDescriptionId: string, text: string): Promise<JobDescriptionConfirmResult> {
365	    if (!text.trim()) throw new Error("Confirmed job description text cannot be empty.");
366	    const timestamp = this.#now();
367	    assertAbsoluteIsoTimestamp(timestamp, "JobDescription.updatedAt");
368	    return runTransaction(this.#database, [STORE_NAMES.applications, STORE_NAMES.jobDescriptions, STORE_NAMES.jobDescriptionTexts], "readwrite", async (tx) => {
369	      const jdStore = tx.objectStore(STORE_NAMES.jobDescriptions);
370	      const textStore = tx.objectStore(STORE_NAMES.jobDescriptionTexts);
371	      const appStore = tx.objectStore(STORE_NAMES.applications);
372	      const jd = await requestToPromise<JobDescription | undefined>(jdStore.get(jobDescriptionId));
373	      if (!jd) throw errorFor("job-description-not-found", "The job description no longer exists.", ACTIONS.selectExisting, { fileName: "", mimeType: "", fileSize: 0 });
374	      const app = await requestToPromise<Application | undefined>(appStore.get(jd.applicationId));
375	      if (!app) throw errorFor("application-not-found", "The application no longer exists.", ACTIONS.selectExisting, metadataFor(jd));
376	      const extracted = await requestToPromise<JobDescriptionText | undefined>(textStore.index("jobDescriptionId_kind").get([jobDescriptionId, "extracted"]));
377	      const pasted = await requestToPromise<JobDescriptionText | undefined>(textStore.index("jobDescriptionId_kind").get([jobDescriptionId, "pasted"]));
378	      const kind: JobDescriptionText["kind"] = extracted?.text === text || pasted?.text === text ? "confirmed" : "manual";
379	      const existing = await requestToPromise<JobDescriptionText | undefined>(textStore.index("jobDescriptionId_kind").get([jobDescriptionId, kind]));
380	      const textRecord: JobDescriptionText = existing
381	        ? { ...existing, text, confirmedAt: timestamp, updatedAt: nextUpdatedTimestamp(timestamp, existing.updatedAt) }
382	        : { id: this.#createId(), createdAt: timestamp, updatedAt: timestamp, jobDescriptionId, kind, text, confirmedAt: timestamp };
383	      if (existing) await requestToPromise(textStore.put(textRecord)); else await requestToPromise(textStore.add(textRecord));
384	      const updatedJd: JobDescription = { ...jd, textSource: kind === "manual" ? "manual" : jd.textSource, textConfirmedAt: timestamp, updatedAt: nextUpdatedTimestamp(timestamp, jd.updatedAt) };
385	      const updatedApp: Application = { ...app, jdText: text, jdFileId: jd.originalFileId, updatedAt: nextUpdatedTimestamp(timestamp, app.updatedAt) };
386	      await requestToPromise(jdStore.put(updatedJd));
387	      await requestToPromise(appStore.put(updatedApp));
388	      return { jobDescription: updatedJd, text: textRecord, application: updatedApp };
389	    });
