 42	function addMissingDefaults(record: StoredRecord, defaults: StoredRecord): boolean {
 43	  let changed = false;
 44	
 45	  for (const [key, value] of Object.entries(defaults)) {
 46	    if (record[key] === undefined) {
 47	      record[key] = value;
 48	      changed = true;
 49	    }
 50	  }
 51	
 52	  const createdAt =
 53	    record.createdAt ?? record.uploadedAt ?? record.usedAt ?? record.startsAt ?? EPOCH;
 54	  if (record.createdAt === undefined) {
 55	    record.createdAt = createdAt;
 56	    changed = true;
 57	  }
 58	  if (record.updatedAt === undefined) {
 59	    record.updatedAt = createdAt;
 60	    changed = true;
 61	  }
 62	
 63	  return changed;
 64	}
 65	
 66	function hasValue<T extends string>(values: readonly T[], value: unknown): value is T {
 67	  return typeof value === "string" && values.includes(value as T);
 68	}
 69	
 70	function validateMigratedRecord(storeName: StoreName, record: StoredRecord): void {
 71	  if (
 72	    storeName === STORE_NAMES.resumes &&
 73	    !hasValue(RESUME_STATUSES, record.status)
 74	  ) {
 75	    throw new Error("Invalid Resume.status in migrated record");
 76	  }
 77	  if (
 78	    storeName === STORE_NAMES.interviews &&
 79	    !hasValue(INTERVIEW_STATUSES, record.status)
 80	  ) {
 81	    throw new Error("Invalid Interview.status in migrated record");
 82	  }
 83	  if (storeName === STORE_NAMES.stages && !hasValue(STAGE_KINDS, record.kind)) {
 84	    throw new Error("Invalid Stage.kind in migrated record");
 85	  }
 86	}
 87	
 88	function migrateStore(
 89	  transaction: IDBTransaction,
 90	  storeName: StoreName,
 91	  defaults: StoredRecord,
 92	  onError: (error: unknown) => void,
 93	): void {
 94	  const request = transaction.objectStore(storeName).openCursor();
 95	
 96	  request.addEventListener("success", () => {
 97	    try {
 98	      const cursor = request.result;
 99	      if (!cursor) {
100	        return;
101	      }
102	
103	      const record = cursor.value as StoredRecord;
104	      const changed = addMissingDefaults(record, defaults);
105	      validateMigratedRecord(storeName, record);
106	      if (changed) {
107	        const updateRequest = cursor.update(record);
108	        updateRequest.addEventListener("error", () => onError(updateRequest.error));
109	      }
110	      cursor.continue();
111	    } catch (error) {
112	      onError(error);
113	      try {
114	        transaction.abort();
115	      } catch {
116	        // A request error may already have aborted the upgrade transaction.
117	      }
118	    }
119	  });
120	  request.addEventListener("error", () => onError(request.error));
121	}
122	
123	export function runMigrations(
124	  transaction: IDBTransaction,
125	  oldVersion: number,
126	  onError: (error: unknown) => void = () => undefined,
127	): void {
128	  if (oldVersion === 0 || oldVersion >= 5) {
129	    return;
130	  }
131	
132	  for (const [storeName, defaults] of Object.entries(DEFAULTS) as Array<
133	    [StoreName, StoredRecord]
134	  >) {
135	    if (transaction.db.objectStoreNames.contains(storeName)) {
136	      migrateStore(transaction, storeName, defaults, onError);
137	    }
138	  }
139	}

