271	  async ingestFile(applicationId: string, file: File): Promise<JobDescriptionIngestionResult> {
272	    const fileType = validateFileMetadata(file);
273	    const data = await file.arrayBuffer();
274	    validateFileContents(file, fileType, new Uint8Array(data));
275	    const fileHash = await sha256(data);
276	    const timestamp = this.#now();
277	    assertAbsoluteIsoTimestamp(timestamp, "JobDescription.createdAt");
278	    let extracted: string | undefined;
279	    try {
280	      const parsed = await this.#parseText(fileType, data.slice(0));
281	      if (!parsed.trim()) throw new Error("No text layer");
282	      extracted = parsed;
283	    } catch {
284	      extracted = undefined;
285	    }
286	    const jobDescriptionId = this.#createId();
287	    const originalFileId = this.#createId();
288	    const jobDescription: JobDescription = {
289	      id: jobDescriptionId, createdAt: timestamp, updatedAt: timestamp,
290	      applicationId, fileName: file.name, fileType, fileSize: file.size, fileHash,
291	      textSource: "extracted", originalFileId,
292	    };
293	    const originalBlob = await new Response(data, { headers: { "content-type": file.type || MIME_TYPES[fileType] } }).blob();
294	    const storedFile: StoredFile = {
295	      id: originalFileId, createdAt: timestamp, updatedAt: timestamp,
296	      ownerType: "job-description", ownerId: jobDescriptionId,
297	      fileName: file.name, fileType,
298	      blob: originalBlob,
299	    };
300	    const extractedText: JobDescriptionText | undefined = extracted ? {
301	      id: this.#createId(), createdAt: timestamp, updatedAt: timestamp,
302	      jobDescriptionId, kind: "extracted", text: extracted,
303	    } : undefined;
304	    await runTransaction(this.#database, [STORE_NAMES.applications, STORE_NAMES.jobDescriptions, STORE_NAMES.originalFiles, STORE_NAMES.jobDescriptionTexts], "readwrite", async (tx) => {
305	      const app = await requestToPromise<Application | undefined>(tx.objectStore(STORE_NAMES.applications).get(applicationId));
306	      if (!app) throw errorFor("application-not-found", "The application no longer exists.", ACTIONS.selectExisting, fileMetadata(file, fileType));
307	      const descriptions = await requestToPromise<JobDescription[]>(tx.objectStore(STORE_NAMES.jobDescriptions).index("applicationId").getAll(applicationId));
308	      const duplicate = descriptions.find((entry) => entry.fileHash === fileHash);
309	      if (duplicate) throw errorFor("duplicate-file", "This job description file was already imported for this application.", ACTIONS.useExisting, { ...fileMetadata(file, fileType), fileHash }, duplicate.id);
310	      await requestToPromise(tx.objectStore(STORE_NAMES.jobDescriptions).add(jobDescription));
311	      await requestToPromise(tx.objectStore(STORE_NAMES.originalFiles).add(storedFile));
312	      if (extractedText) await requestToPromise(tx.objectStore(STORE_NAMES.jobDescriptionTexts).add(extractedText));
313	    });
314	    const metadata = metadataFor(jobDescription, storedFile.blob.type);
315	    if (extractedText) {
316	      this.#logger({ event: "job-description-ingested", metadata });
317	      return { outcome: "needs-review", jobDescription, extractedText };
318	    }
319	    const recovery = { code: "extraction-failed" as const, action: ACTIONS.pasteText, metadata };
320	    this.#logger({ event: "job-description-extraction-failed", metadata });
321	    return { outcome: "extraction-failed", jobDescription, recovery };
322	  }
